In tools/compute_limits.js, score the limit shapes without relying on arm detection. Measure head and body with the tool, then add the arms analytically:
```js
function armVolume(fig, deg) { // both arms, the length whose axis is outside the body outline
  const d = fig.dims, st = d.armStations, sj = d.shoulderJoint, a = deg * Math.PI / 180;
  const body = fig.front.find((p) => p.name === 'body').poly, L = st.Lu + st.Lf, n = 600;
  const rad = (S, s) => { if (s <= S[0][0]) return S[0][1]; for (let k = 1; k < S.length; k++) if (s <= S[k][0]) return S[k-1][1] + (S[k][1]-S[k-1][1]) * (s-S[k-1][0]) / (S[k][0]-S[k-1][0]); return S[S.length-1][1]; };
  let v = 0;
  for (let i = 0; i < n; i++) { const s = (i + 0.5) / n * L, r = s < st.Lu ? rad(st.upper, s) : rad(st.fore, s - st.Lu);
    if (!Fig.pointInPoly([sj[0] + Math.sin(a) * s, sj[1] - Math.cos(a) * s], body)) v += Math.PI * r * r * L / n; }
  return 2 * v;
}
function scoreAt(m, f) {
  const deg = Math.max(35, Fig.armRestAngle((x) => m.make(f, x)) + 2), fig = m.make(f, deg);
  const r = measureViews({ front: fig.front.filter((p) => p.name === 'head' || p.name === 'body'), side: fig.side }, H, m.levels, 800).res;
  return 1.8 * (r.volume_m3.value + armVolume(fig, deg)) * 1060 * 0.925 / Math.pow(H, 3);
}
```
